            .modifiers(Frame::new(Some(size::FILL), None, None)),
            button("Increment").modifiers(TapGesture::new(move || on_increment())),
        ]
        .with(|v| {
            v.spacing(8.0);
        })
        .modifiers(Padding(16.0)),
        TextField::with(|t| {
            t.placeholder("Your name");
            t.text(name);
