     static QT_LOCK: Mutex<()> = Mutex::new(());

     fn with_qt(f: impl FnOnce()) {
         let _guard = QT_LOCK.lock().unwrap_or_else(|e| e.into_inner());
         std::env::set_var("QT_QPA_PLATFORM", "offscreen");
         std::env::set_var("QT_QUICK_BACKEND", "software");
