         // SAFETY: the C++ layer passes a pointer valid for the call duration.
         let ev = unsafe { &*ev };
         EVENTS
             .lock()
             .unwrap_or_else(|e| e.into_inner())
             .push((ev.kind, ev.node_id, ev.value));
